/// `tab_complete` (serverbound play).
#[derive(Debug, Clone, PartialEq)]
pub struct TabComplete<const V: i32> {
    /// `text`
    pub text: ByteString,
    /// `block`
    pub block: Option<BlockPos>,
}
#[cfg(feature = "v1_8")]
impl<const V: i32> Decode for TabComplete<V> {
    fn decode(r: &mut Reader<'_>) -> DecodeResult<Self> {
        Ok({
            let v1 = r.read_string()?;
            let v2 = if r.read_bool()? {
                Some(BlockPos::read(r, PositionLayout::Xyz)?)
            } else {
                None
            };
            Self {
                text: v1,
                block: v2,
            }
        })
    }
}
#[cfg(feature = "v1_8")]
impl<const V: i32> Encode for TabComplete<V> {
    fn encode(&self, w: &mut BytesMut) -> EncodeResult {
        w.put_string(&(*self).text)?;
        match &(*self).block {
            Some(v1) => {
                w.put_u8(1);
                (*v1).write(w, PositionLayout::Xyz)?;
            }
            None => w.put_u8(0),
        }
        Ok(())
    }
}
#[cfg(feature = "v1_8")]
#[cfg(feature = "testgen")]
impl<const V: i32> Generate for TabComplete<V> {
    fn generate(g: &mut Gen) -> Self {
        {
            let v1 = g.string();
            let v2 = if g.bool() { Some(g.position()) } else { None };
            Self {
                text: v1,
                block: v2,
            }
        }
    }
}

