impl<const V: i32> Generate for Spectate<V> {
    fn generate(g: &mut Gen) -> Self {
        {
            let v1 = g.uuid();
            Self { target: v1 }
        }
    }
}

#[cfg(feature = "v1_8")]
/// `resource_pack_receive` (serverbound play).
#[derive(Debug, Clone, PartialEq)]
pub struct ResourcePackReceive<const V: i32> {
    /// `hash`
    pub hash: ByteString,
    /// `result`
    pub result: i32,
}
#[cfg(feature = "v1_8")]
impl<const V: i32> Decode for ResourcePackReceive<V> {
    fn decode(r: &mut Reader<'_>) -> DecodeResult<Self> {
        Ok({
            let v1 = r.read_string()?;
            let v2 = r.read_varint()?;
            Self {
                hash: v1,
                result: v2,
            }
        })
    }
}
#[cfg(feature = "v1_8")]
impl<const V: i32> Encode for ResourcePackReceive<V> {
    fn encode(&self, w: &mut BytesMut) -> EncodeResult {
        w.put_string(&(*self).hash)?;
        w.put_varint((*self).result);
        Ok(())
    }
}
#[cfg(feature = "v1_8")]
#[cfg(feature = "testgen")]
impl<const V: i32> Generate for ResourcePackReceive<V> {
    fn generate(g: &mut Gen) -> Self {
        {
            let v1 = g.string();
            let v2 = (g.int_in(-2147483648, 2147483647, &[]) as i32);
            Self {
                hash: v1,
                result: v2,
            }
        }
    }
}
